CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE clauses (
    id          bigserial PRIMARY KEY,
    contract_id bigint NOT NULL,
    team_id     int    NOT NULL,       -- used for permission filtering
    body        text   NOT NULL,
    embedding   vector(1024)           -- produced by an embedding model
);

-- Approximate nearest-neighbour index using cosine distance
CREATE INDEX ON clauses USING hnsw (embedding vector_cosine_ops);

-- $1 is the query embedding, $2 the user's team
SELECT id, contract_id, left(body, 120) AS preview
FROM clauses
WHERE team_id = $2
ORDER BY embedding <=> $1              -- <=> is cosine distance
LIMIT 5;

import hashlib

FLAGS = {
    "ai_summary": {"enabled": True, "percent": 25, "allow": {"team-motor-3"}},
}

def bucket(user_id: str) -> int:
    # stable 0-99 bucket so a user always gets the same answer
    return int(hashlib.sha256(user_id.encode()).hexdigest(), 16) % 100

def is_on(flag: str, user_id: str, team: str) -> bool:
    f = FLAGS.get(flag)
    if not f or not f["enabled"]:
        return False                  # kill switch: set enabled False
    if team in f["allow"]:
        return True                   # pilot team always on
    return bucket(user_id) < f["percent"]

print(is_on("ai_summary", "user-8812", "team-home-1"))

import random, time, requests

def call_with_backoff(method, url, max_tries=6, **kw):
    for attempt in range(max_tries):
        r = requests.request(method, url, timeout=30, **kw)
        if r.status_code not in (429, 503):
            r.raise_for_status()
            return r
        wait = r.headers.get("Retry-After")
        if wait and wait.isdigit():
            delay = int(wait)                       # server told us how long
        else:
            delay = min(60, 2 ** attempt) + random.uniform(0, 1)  # backoff + jitter
        time.sleep(delay)
    raise RuntimeError(f"Gave up after {max_tries} tries: {url}")
